import React from 'react';

import { TableColumn } from '../../../types/shared-table-types.js';

export interface TableColumnsActionsProps {
  /**
   * The accessor/id of the column the user actions belong to. If this property is not set,
   * the configuration is used as a fallback for all columns where no user actions are defined explicitly.
   */
  column?: string;

  children: (column: TableColumn) => JSX.Element | null;
}

/**
 * Configuration component used for defining user actions for table columns.
 * This component can only be used as a child element of `<DataTable.UserActions>`.
 */
export const ColumnActions = ({ children }: TableColumnsActionsProps) => (
  <>{children}</> // eslint-disable-line react/jsx-no-useless-fragment
);

ColumnActions.displayName = 'DataTable.ColumnActions';
